class Solution:
    def isValid(self, s: str) -> bool:
        pairs = {')': '(', ']': '[', '}': '{'}
        st = []
        for ch in s:
            if ch not in pairs:        # 左括号
                st.append(ch)
            elif not st or st.pop() != pairs[ch]:
                return False           # 右括号无匹配
        return not st                  # 栈空才有效

class MinStack:
    def __init__(self):
        self.st = []
        self.min_st = []          # min_st[i] = st[:i+1] 的最小值

    def push(self, val: int) -> None:
        self.st.append(val)
        cur = self.min_st[-1] if self.min_st else val
        self.min_st.append(min(cur, val))

    def pop(self) -> None:
        self.st.pop()
        self.min_st.pop()

    def top(self) -> int:
        return self.st[-1]

    def getMin(self) -> int:
        return self.min_st[-1]

class Solution:
    def decodeString(self, s: str) -> str:
        cur = ""
        num = 0
        st = []  # 保存 (外层串, 重复次数)
        for ch in s:
            if ch.isdigit():
                num = num * 10 + int(ch)
            elif ch == '[':
                st.append((cur, num))   # 记住外层状态
                cur, num = "", 0
            elif ch == ']':
                prev, k = st.pop()
                cur = prev + cur * k    # 内层展开后拼回外层
            else:
                cur += ch
        return cur

class Solution:
    def dailyTemperatures(self, temperatures: List[int]) -> List[int]:
        n = len(temperatures)
        ans = [0] * n
        st = []  # 下标，对应温度单调递减
        for i, t in enumerate(temperatures):
            while st and temperatures[st[-1]] < t:
                j = st.pop()
                ans[j] = i - j       # j 的下一个更高温在 i
            st.append(i)
        return ans

class Solution:
    def largestRectangleArea(self, heights: List[int]) -> int:
        st = []            # 下标，高度单调递增
        best = 0
        hs = heights + [0] # 末尾哨兵，逼出栈中全部元素
        for i, h in enumerate(hs):
            while st and hs[st[-1]] >= h:
                j = st.pop()
                left = st[-1] if st else -1
                best = max(best, hs[j] * (i - left - 1))
            st.append(i)
        return best
